<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="账户名称"><el-input v-model="query.accountName" clearable @keyup.enter="load"/></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-button type="primary" icon="Plus" @click="openAdd" v-hasPermi="['research:simulation:add']">创建模拟账户</el-button><el-table v-loading="loading" :data="rows" class="mt12"><el-table-column prop="accountName" label="账户名称"/><el-table-column prop="initialBalance" label="初始资金"/><el-table-column prop="availableBalance" label="可用余额"/><el-table-column prop="totalPnl" label="总盈亏"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="remove(row)" v-hasPermi="['research:simulation:remove']">删除</el-button></template></el-table-column></el-table><pagination v-show="total" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/><el-dialog v-model="dialog" title="创建模拟账户" width="460px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="账户名称" prop="accountName"><el-input v-model="form.accountName"/></el-form-item><el-form-item label="初始资金" prop="initialBalance"><el-input-number v-model="form.initialBalance" :min="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="ResearchSimulation">import { addSimulation, delSimulation, listSimulation } from '@/api/project-research/research'
const { proxy }=getCurrentInstance();const loading=ref(false),dialog=ref(false),total=ref(0),rows=ref([]),formRef=ref();const query=reactive({pageNum:1,pageSize:10,accountName:undefined});const form=reactive({});const rules={accountName:[{required:true,message:'账户名称不能为空'}],initialBalance:[{required:true,message:'请输入初始资金'}]};function load(){loading.value=true;listSimulation(query).then(r=>{rows.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)}function openAdd(){Object.assign(form,{accountName:'',initialBalance:100000});dialog.value=true}function save(){formRef.value.validate(v=>{if(v)addSimulation(form).then(()=>{proxy.$modal.msgSuccess('创建成功');dialog.value=false;load()})})}function remove(r){proxy.$modal.confirm('确认删除该模拟账户吗？').then(()=>delSimulation(r.id)).then(load)}load()</script><style scoped>.mt12{margin-top:12px}</style>
